(function(){
  'use strict';
  function bits(s){
    var t=String(s||'').replace(/[^01]/g,'');
    var o=[]; for(var i=0;i<t.length;i++) o.push(t.charCodeAt(i)-48);
    return o;
  }
  function str(b){ return b.join(''); }
  function isPow2(n){ return n>0 && (n & (n-1))===0; }
  function parityCount(k){
    var r=0;
    while(Math.pow(2,r) < k+r+1) r++;
    return r;
  }
  // 编码：数据位放非 2 的幂位置，校验位放 2 的幂位置（1-based）
  function encode(dataBits, extended){
    var d=bits(dataBits);
    if(!d.length) return {value:null, error:'数据位为空'};
    if(d.length>64) return {value:null, error:'数据位过多（'+d.length+'），上限 64'};
    var k=d.length, r=parityCount(k), n=k+r;
    var cw=new Array(n+1).fill(0);   // 1-based
    var di=0;
    for(var p=1;p<=n;p++) if(!isPow2(p)) cw[p]=d[di++];
    var parities=[];
    for(var b=0;b<r;b++){
      var pos=Math.pow(2,b), x=0, covers=[];
      for(var q=1;q<=n;q++){
        if(q===pos) continue;
        if(q & pos){ x^=cw[q]; covers.push(q); }
      }
      cw[pos]=x;
      parities.push({pos:pos, value:x, covers:covers});
    }
    var out=cw.slice(1);
    var res={code:str(out), n:n, k:k, r:r, parities:parities, rate:k+'/'+n,
             scheme:'Hamming('+n+','+k+')'};
    if(extended){
      var overall=0;
      for(var i=0;i<out.length;i++) overall^=out[i];
      res.code = String(overall)+res.code;   // P0 在最前
      res.n = n+1;
      res.overall = overall;
      res.scheme = 'Extended Hamming('+(n+1)+','+k+') SECDED';
    }
    return {value:res, error:''};
  }

  function decode(codeStr, extended){
    var c=bits(codeStr);
    if(!c.length) return {value:null, error:'码字为空'};
    var overall=null, body=c;
    if(extended){
      if(c.length<2) return {value:null, error:'扩展汉明码至少需要 2 位'};
      overall=c[0]; body=c.slice(1);
    }
    var n=body.length;
    var r=0; while(Math.pow(2,r)<=n) r++;
    // n = k + r，需满足 2^r >= n+1
    while(Math.pow(2,r) < n+1) r++;
    var k=n-r;
    if(k<1) return {value:null, error:'码字长度 '+n+' 太短，无有效数据位'};
    var cw=[0].concat(body);
    var syn=0, checks=[];
    for(var b=0;b<r;b++){
      var pos=Math.pow(2,b), x=0;
      for(var q=1;q<=n;q++) if(q & pos) x^=cw[q];
      checks.push({pos:pos, fail:x===1});
      if(x) syn|=pos;
    }
    var res={n:body.length, k:k, r:r, syndrome:syn, checks:checks,
             scheme:(extended?'Extended Hamming('+(n+1)+','+k+') SECDED':'Hamming('+n+','+k+')')};
    if(extended){
      var parityAll=overall;
      for(var i=0;i<body.length;i++) parityAll^=body[i];
      res.overallFail = parityAll===1;
      if(syn===0 && !res.overallFail){ res.status='无错误'; }
      else if(syn!==0 && res.overallFail){ res.status='检出 1 位错误，已纠正'; res.errorPos=syn; }
      else if(syn===0 && res.overallFail){ res.status='总校验位 P0 自身出错，数据可用'; res.errorPos=0; }
      else { res.status='检出 2 位错误，无法纠正'; res.uncorrectable=true; }
    } else {
      if(syn===0) res.status='无错误';
      else if(syn>n){ res.status='综合征 '+syn+' 超出码长，检出错误但无法定位'; res.uncorrectable=true; }
      else { res.status='检出 1 位错误，已纠正'; res.errorPos=syn; }
    }
    var fixed=cw.slice();
    if(res.errorPos && res.errorPos<=n) fixed[res.errorPos] ^= 1;
    var dataOut=[];
    for(var p=1;p<=n;p++) if(!isPow2(p)) dataOut.push(fixed[p]);
    res.corrected = str(fixed.slice(1));
    res.data = res.uncorrectable ? null : str(dataOut);
    return {value:res, error:''};
  }

  function flip(codeStr, pos1){
    var c=bits(codeStr);
    if(pos1<1 || pos1>c.length) return codeStr;
    c[pos1-1] ^= 1;
    return str(c);
  }
  function textToBits(s){
    var o='';
    for(var i=0;i<s.length;i++){
      var v=s.charCodeAt(i)&255, t=v.toString(2);
      while(t.length<8) t='0'+t;
      o+=t;
    }
    return o;
  }
  function bitsToText(b){
    var t=bits(b), s='';
    for(var i=0;i+7<t.length;i+=8){
      var v=0; for(var j=0;j<8;j++) v=(v<<1)|t[i+j];
      s+=String.fromCharCode(v);
    }
    return s;
  }
  function overhead(k, extended){
    var r=parityCount(k);
    var n=k+r+(extended?1:0);
    return {n:n, r:r+(extended?1:0), percent:Math.round((n-k)/k*1000)/10};
  }

  var API={encode:encode, decode:decode, flip:flip, bits:bits, parityCount:parityCount,
           isPow2:isPow2, textToBits:textToBits, bitsToText:bitsToText, overhead:overhead};
  if(typeof module!=='undefined' && module.exports) module.exports=API;
  if(typeof window!=='undefined') window.__HammingForge__=API;
})();
